        /// <summary>
        /// Builds the idempotent upsert of the whole catalog from <see cref="Seed"/>.
        /// </summary>
        /// <returns>
        /// One <c>INSERT ... ON CONFLICT (id) DO UPDATE</c> statement, ordered so every parent is
        /// inserted before its children.
        /// </returns>
        /// <remarks>
        /// <c>active</c> is deliberately <b>not</b> updated on conflict: retiring a region is a
        /// deactivation (<c>active = false</c>, docs/domain.md#region-catalog), and re-applying the
        /// seed must not silently resurrect a region a human switched off.
        /// </remarks>
        public static string BuildSeedStatement()
        {
            var values = Seed.Select(region => $"({string.Join(
                ", ",
                Literal(region.Id),
                Literal(region.Label),
                Literal(SourceName),
                "true",
                Literal(region.SourceId),
                region.ParentId is null ? "NULL" : Literal(region.ParentId))})");

            return $"""
                INSERT INTO tour_search.regions (id, label, source, active, source_id, parent_id)
                VALUES
                    {string.Join(",\n    ", values)}
                ON CONFLICT (id) DO UPDATE SET
                    label = EXCLUDED.label,
                    source = EXCLUDED.source,
                    source_id = EXCLUDED.source_id,
                    parent_id = EXCLUDED.parent_id;
                """;
        }

