        {
            foreach (var generation in Seed.GroupBy(region => region.ParentId is null).OrderBy(group => group.Key))
            {
                yield return $"DELETE FROM tour_search.regions WHERE id IN ({string.Join(", ", generation.Select(region => Literal(region.Id)))});";
            }
        }

